        chosen = {
            edge for index, edge in enumerate(edges) if (mask >> index) & 1
        }
        triangle_free = all(
            not ({(i, j), (i, k), (j, k)} <= chosen)
            for i, j, k in itertools.combinations(range(n), 3)
        )
